    destruct r as [|r].
    { eapply narm_reach; [exact nrules_sound_0RB0LA_1LA0RC_0LD1RC_1RB1LD | exact ok_iarm0_3_0RB0LA_1LA0RC_0LD1RC_1RB1LD]. }
    exfalso; lia.
