Lemma farm_rhs_0RB0LA_1LA0RC_0LD1RC_1RB1LD : forall r ph, 0 < r -> r < 4 + 1 ->
  ph < 1 ->
  lr_rhs (farm_0RB0LA_1LA0RC_0LD1RC_1RB1LD r ph)
    = cls_conf FAM (run_side FAM (f_mid (fam_fill FAM ph)) (fm1_0RB0LA_1LA0RC_0LD1RC_1RB1LD r ph)
                      (astride 4 1 r) (fm2_0RB0LA_1LA0RC_0LD1RC_1RB1LD r ph)
