(** The fill arms, one per arm index and PHASE.  Both tails are known
    empty -- they are the only arms that see the end of the counter -- and
    the arm at index [r] has [r] guaranteed block copies materialised into
    [s_pre], without which it has no chain at all.  [fm1]/[fm2] say how the
    fill target's own guaranteed copies divide about the block.

    The phase is the second index because the fill arm is the ONLY one that
    sees a terminator: it leaves from the terminator of its own phase and
    lands on the terminator of the phase its law names.  The interior arms
    keep the terminator in the opaque tail and are phase-free. *)
Definition farm_0RB0LA_1LA1RC_0LD0RC_1LD1RB (r ph : nat) : LRule :=
  match r, ph with
  | 1, 0 => farm1_0_0RB0LA_1LA1RC_0LD0RC_1LD1RB
  | 2, 0 => farm2_0_0RB0LA_1LA1RC_0LD0RC_1LD1RB
  | 3, 0 => farm3_0_0RB0LA_1LA1RC_0LD0RC_1LD1RB
  | 4, 0 => farm4_0_0RB0LA_1LA1RC_0LD0RC_1LD1RB
  | _, _ => farm1_0_0RB0LA_1LA1RC_0LD0RC_1LD1RB  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_0RB0LA_1LA1RC_0LD0RC_1LD1RB (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | 2, 0 => 1 | 3, 0 => 1 | 4, 0 => 1 | _, _ => 0 end.
Definition fm2_0RB0LA_1LA1RC_0LD0RC_1LD1RB (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 0 | 2, 0 => 1 | 3, 0 => 2 | 4, 0 => 3 | _, _ => 0 end.

(** One chain per UNPINNED INSTRUCTION per fill arm, at the VISIT PHASE
    0.  [fire_of_run_instr] turns each into a fire of that instruction,
    and [tops_cofinal_at] says the tops of that phase keep coming.  The fill
    arm is the counter's overflow, so this is where the rare instruction of
    a sparse row is witnessed. *)
Definition vis_0RB0LA_1LA1RC_0LD0RC_1LD1RB (r : nat) (t : Instr) : list lstep :=
  match r, t with
  | 1, (StA, S0) => []
  | 1, (StA, S1) => [SWinR 5]
  | 1, (StB, S0) => [SWinR 4]
  | 1, (StB, S1) => [SWin 1]
  | 1, (StC, S0) => [SWinR 2]
  | 1, (StC, S1) => [SWinR 10]
  | 1, (StD, S0) => [SWinR 12]
  | 1, (StD, S1) => [SWinR 3]
  | 2, (StA, S0) => []
  | 2, (StA, S1) => [SWinR 10]
  | 2, (StB, S0) => [SWinR 9]
  | 2, (StB, S1) => [SWin 1]
  | 2, (StC, S0) => [SWinR 3]
  | 2, (StC, S1) => [SWin 2]
  | 2, (StD, S0) => [SWinR 4]
  | 2, (StD, S1) => [SWinR 5]
  | 3, (StA, S0) => []
  | 3, (StA, S1) => [SWinR 17]
  | 3, (StB, S0) => [SWinR 16]
  | 3, (StB, S1) => [SWin 1]
  | 3, (StC, S0) => [SWinR 4]
  | 3, (StC, S1) => [SWin 2]
  | 3, (StD, S0) => [SWinR 5]
  | 3, (StD, S1) => [SWinR 7]
  | 4, (StA, S0) => [SWin 0]
  | 4, (StA, S1) => [SWin 9]
  | 4, (StB, S0) => [SWin 8]
  | 4, (StB, S1) => [SWin 1]
  | 4, (StC, S0) => [SWin 4;SCycR 1;SWinR 1]
  | 4, (StC, S1) => [SWin 2]
  | 4, (StD, S0) => [SWin 4;SCycR 1;SWinR 2]
  | 4, (StD, S1) => [SWin 4;SCycR 1;SWinR 2;SCycL 1 0;SWin 3]
  | _, _ => []
  end.

(** ...each after its segment program: a visit that fires past the rounds
