Definition vsegs_0RB0LA_1LA1RC_0LD0RC_1LD1RB (r : nat) (t : Instr) : list nseg :=
  match r, t with
  | 1, (StA, S0) => []
  | 1, (StA, S1) => []
  | 1, (StB, S0) => []
  | 1, (StB, S1) => []
  | 1, (StC, S0) => []
  | 1, (StC, S1) => []
  | 1, (StD, S0) => []
  | 1, (StD, S1) => []
  | 2, (StA, S0) => []
  | 2, (StA, S1) => []
  | 2, (StB, S0) => []
  | 2, (StB, S1) => []
  | 2, (StC, S0) => []
  | 2, (StC, S1) => []
  | 2, (StD, S0) => []
  | 2, (StD, S1) => []
  | 3, (StA, S0) => []
  | 3, (StA, S1) => []
  | 3, (StB, S0) => []
  | 3, (StB, S1) => []
  | 3, (StC, S0) => []
  | 3, (StC, S1) => []
  | 3, (StD, S0) => []
  | 3, (StD, S1) => []
  | 4, (StA, S0) => []
  | 4, (StA, S1) => [NCh [RB (SWin 4);RB (SCycR 1);RB (SWinR 2);RB (SCycL 1 0);RB (SWin 4);RB (SFoldR 1)]; NDn 1 [S1] [] 0 1 0 (mkS [S0] [] 0 0 []) (mkS [] [] 0 0 []) true]
  | 4, (StB, S0) => [NCh [RB (SWin 4);RB (SCycR 1);RB (SWinR 2);RB (SCycL 1 0);RB (SWin 4);RB (SFoldR 1)]; NDn 1 [S1] [] 0 1 0 (mkS [S0] [] 0 0 []) (mkS [] [] 0 0 []) true]
  | 4, (StB, S1) => []
  | 4, (StC, S0) => []
  | 4, (StC, S1) => []
  | 4, (StD, S0) => []
  | 4, (StD, S1) => []
  | _, _ => []
  end.

Lemma iarm_reach_0RB0LA_1LA1RC_0LD0RC_1LD1RB : forall d r,
  d < fm_b FAM - 1 -> r < 3 + 1 ->
  ReachL tm (negb (fm_left FAM)) (fm_left FAM)
    (lr_lhs (iarm_0RB0LA_1LA1RC_0LD0RC_1LD1RB d r)) (lr_rhs (iarm_0RB0LA_1LA1RC_0LD0RC_1LD1RB d r)).
Proof.
  intros d r Hd Hr. vm_compute in Hd.
  destruct d as [|d].
  {
    destruct r as [|r].
