Definition iarm_1RB0LC_0LA0RB_0RD1LC_1LA1RD (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB0LC_0LA0RB_0RD1LC_1LA1RD
  | 0, 1 => iarm0_1_1RB0LC_0LA0RB_0RD1LC_1LA1RD
  | 0, 2 => iarm0_2_1RB0LC_0LA0RB_0RD1LC_1LA1RD
  | 0, 3 => iarm0_3_1RB0LC_0LA0RB_0RD1LC_1LA1RD
  | _, _ => iarm0_0_1RB0LC_0LA0RB_0RD1LC_1LA1RD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

(** The fill arms, one per arm index and PHASE.  Both tails are known
    empty -- they are the only arms that see the end of the counter -- and
    the arm at index [r] has [r] guaranteed block copies materialised into
    [s_pre], without which it has no chain at all.  [fm1]/[fm2] say how the
    fill target's own guaranteed copies divide about the block.

    The phase is the second index because the fill arm is the ONLY one that
    sees a terminator: it leaves from the terminator of its own phase and
    lands on the terminator of the phase its law names.  The interior arms
    keep the terminator in the opaque tail and are phase-free. *)
Definition farm_1RB0LC_0LA0RB_0RD1LC_1LA1RD (r ph : nat) : LRule :=
  match r, ph with
  | 1, 0 => farm1_0_1RB0LC_0LA0RB_0RD1LC_1LA1RD
  | 2, 0 => farm2_0_1RB0LC_0LA0RB_0RD1LC_1LA1RD
  | 3, 0 => farm3_0_1RB0LC_0LA0RB_0RD1LC_1LA1RD
  | 4, 0 => farm4_0_1RB0LC_0LA0RB_0RD1LC_1LA1RD
  | _, _ => farm1_0_1RB0LC_0LA0RB_0RD1LC_1LA1RD  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_1RB0LC_0LA0RB_0RD1LC_1LA1RD (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | 2, 0 => 1 | 3, 0 => 1 | 4, 0 => 1 | _, _ => 0 end.
Definition fm2_1RB0LC_0LA0RB_0RD1LC_1LA1RD (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 0 | 2, 0 => 1 | 3, 0 => 2 | 4, 0 => 3 | _, _ => 0 end.

(** One chain per UNPINNED INSTRUCTION per fill arm, at the VISIT PHASE
    0.  [fire_of_run_instr] turns each into a fire of that instruction,
    and [tops_cofinal_at] says the tops of that phase keep coming.  The fill
    arm is the counter's overflow, so this is where the rare instruction of
    a sparse row is witnessed. *)
Definition vis_1RB0LC_0LA0RB_0RD1LC_1LA1RD (r : nat) (t : Instr) : list lstep :=
  match r, t with
  | 1, (StA, S0) => [SWinL 4]
  | 1, (StA, S1) => [SWin 1]
  | 1, (StB, S0) => []
  | 1, (StB, S1) => [SWinL 5]
  | 1, (StC, S0) => [SWinL 2]
  | 1, (StC, S1) => [SWinL 10]
  | 1, (StD, S0) => [SWinL 3]
  | 1, (StD, S1) => [SWinL 12]
  | 2, (StA, S0) => [SWinL 9]
  | 2, (StA, S1) => [SWin 1]
  | 2, (StB, S0) => []
  | 2, (StB, S1) => [SWinL 10]
  | 2, (StC, S0) => [SWinL 3]
  | 2, (StC, S1) => [SWin 2]
  | 2, (StD, S0) => [SWinL 5]
  | 2, (StD, S1) => [SWinL 4]
  | 3, (StA, S0) => [SWinL 16]
  | 3, (StA, S1) => [SWin 1]
  | 3, (StB, S0) => []
  | 3, (StB, S1) => [SWinL 17]
  | 3, (StC, S0) => [SWinL 4]
  | 3, (StC, S1) => [SWin 2]
  | 3, (StD, S0) => [SWinL 7]
  | 3, (StD, S1) => [SWinL 5]
  | 4, (StA, S0) => [SWin 8]
  | 4, (StA, S1) => [SWin 1]
  | 4, (StB, S0) => [SWin 0]
  | 4, (StB, S1) => [SWin 9]
  | 4, (StC, S0) => [SWin 4;SCycL 1 0;SWinL 1]
  | 4, (StC, S1) => [SWin 2]
  | 4, (StD, S0) => [SWin 4;SCycL 1 0;SWinL 2;SCycR 1;SWin 3]
  | 4, (StD, S1) => [SWin 4;SCycL 1 0;SWinL 2]
  | _, _ => []
  end.

(** ...each after its segment program: a visit that fires past the rounds
    of a nested fill arm first runs that arm's program up to them. *)
Definition vsegs_1RB0LC_0LA0RB_0RD1LC_1LA1RD (r : nat) (t : Instr) : list nseg :=
  match r, t with
  | 1, (StA, S0) => []
  | 1, (StA, S1) => []
  | 1, (StB, S0) => []
  | 1, (StB, S1) => []
  | 1, (StC, S0) => []
  | 1, (StC, S1) => []
  | 1, (StD, S0) => []
  | 1, (StD, S1) => []
  | 2, (StA, S0) => []
  | 2, (StA, S1) => []
  | 2, (StB, S0) => []
  | 2, (StB, S1) => []
  | 2, (StC, S0) => []
  | 2, (StC, S1) => []
  | 2, (StD, S0) => []
  | 2, (StD, S1) => []
  | 3, (StA, S0) => []
  | 3, (StA, S1) => []
  | 3, (StB, S0) => []
  | 3, (StB, S1) => []
  | 3, (StC, S0) => []
  | 3, (StC, S1) => []
  | 3, (StD, S0) => []
  | 3, (StD, S1) => []
  | 4, (StA, S0) => [NCh [RB (SWin 4);RB (SCycL 1 0);RB (SWinL 2);RB (SCycR 1);RB (SWin 4);RB (SFoldL 1)]; NDn 1 [] [S1] 0 1 0 (mkS [] [] 0 0 []) (mkS [S0] [] 0 0 []) true]
  | 4, (StA, S1) => []
  | 4, (StB, S0) => []
  | 4, (StB, S1) => [NCh [RB (SWin 4);RB (SCycL 1 0);RB (SWinL 2);RB (SCycR 1);RB (SWin 4);RB (SFoldL 1)]; NDn 1 [] [S1] 0 1 0 (mkS [] [] 0 0 []) (mkS [S0] [] 0 0 []) true]
  | 4, (StC, S0) => []
  | 4, (StC, S1) => []
  | 4, (StD, S0) => []
  | 4, (StD, S1) => []
  | _, _ => []
  end.

