Lemma bootl_1RB0LC_0LA0RB_0RD1LC_1LA1RD :
  stepn tm 1 InitES = Some (lift (fam_cfg FAM ([1], 0, 0))).
Proof.
  assert (H : match csteps tm 1 c0 with
              | Some c => ceqb c (fam_cfg FAM ([1], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm 1 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** The machine-level theorem, at the INSTRUCTION level, through the nested
    board [LadderCheckNestTr.boardN_neverqhtr]. *)
Theorem nqhtr_1RB0LC_0LA0RB_0RD1LC_1LA1RD : NeverQuasiHaltsTr tm_1RB0LC_0LA0RB_0RD1LC_1LA1RD.
Proof.
  eapply (boardN_neverqhtr tm_1RB0LC_0LA0RB_0RD1LC_1LA1RD pins_1RB0LC_0LA0RB_0RD1LC_1LA1RD FAM 1
                           iarm_1RB0LC_0LA0RB_0RD1LC_1LA1RD 3 1
                           farm_1RB0LC_0LA0RB_0RD1LC_1LA1RD 4 1
                           fm1_1RB0LC_0LA0RB_0RD1LC_1LA1RD fm2_1RB0LC_0LA0RB_0RD1LC_1LA1RD 0
                           nrules vsegs_1RB0LC_0LA0RB_0RD1LC_1LA1RD vis_1RB0LC_0LA0RB_0RD1LC_1LA1RD
                           [1] 0).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_1RB0LC_0LA0RB_0RD1LC_1LA1RD.
  - repeat constructor.
  - vm_compute; lia.
