Definition iarm_1RB0LD_0LC0RA_1RA1LC_1LA1RA (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB0LD_0LC0RA_1RA1LC_1LA1RA
  | 0, 1 => iarm0_1_1RB0LD_0LC0RA_1RA1LC_1LA1RA
  | _, _ => iarm0_0_1RB0LD_0LC0RA_1RA1LC_1LA1RA   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

(** The fill arms, one per arm index and PHASE.  Both tails are known
