Lemma ok_arm15_1RB0RC_0LA0RB_0LD1RC_1LA1LD :
  check_arm tm true true rules arm15_1RB0RC_0LA0RB_0LD1RC_1LA1LD ch_arm15_1RB0RC_0LA0RB_0LD1RC_1LA1LD = true.
