Lemma vis_ok_1RB0RD_1LC1LB_0RA0LC_1RA1RD : forall r t, ~ In t pins_1RB0RD_1LC1LB_0RA0LC_1RA1RD -> 0 < r ->
  r < 1 + 1 ->
  nfire tm true true nrules (vsegs_1RB0RD_1LC1LB_0RA0LC_1RA1RD r t) (vis_1RB0RD_1LC1LB_0RA0LC_1RA1RD r t)
    (lr_lhs (farm_1RB0RD_1LC1LB_0RA0LC_1RA1RD r 0)) = Some t.
Proof.
  intros r t Hnp H0 Hr.
  destruct r as [|r].
