  | 2, (StA, S1) => []
  | 2, (StB, S0) => []
  | 2, (StB, S1) => []
  | 2, (StC, S0) => []
  | 2, (StC, S1) => []
  | 2, (StD, S0) => []
  | 2, (StD, S1) => []
  | 3, (StA, S0) => [NCh [RB (SWin 1);RB (SFoldL 1)]; NUp 2 [S1] [] 0 1 1 (mkS [] [] 0 0 []) (mkS [S0] [] 0 0 []) false]
  | 3, (StA, S1) => []
  | 3, (StB, S0) => []
  | 3, (StB, S1) => [NCh [RB (SWin 1);RB (SFoldL 1)]; NUp 2 [S1] [] 0 1 1 (mkS [] [] 0 0 []) (mkS [S0] [] 0 0 []) false]
  | 3, (StC, S0) => [NCh [RB (SWin 1);RB (SFoldL 1)]; NUp 2 [S1] [] 0 1 1 (mkS [] [] 0 0 []) (mkS [S0] [] 0 0 []) false; NCh [RB (SWin 1);RB (SWinL 2)]; NDn 3 [S0] [] 0 1 0 (mkS [S1] [] 0 0 []) (mkS [] [] 0 0 []) true]
  | 3, (StC, S1) => [NCh [RB (SWin 1);RB (SFoldL 1)]; NUp 2 [S1] [] 0 1 1 (mkS [] [] 0 0 []) (mkS [S0] [] 0 0 []) false]
  | 3, (StD, S0) => [NCh [RB (SWin 1);RB (SFoldL 1)]; NUp 2 [S1] [] 0 1 1 (mkS [] [] 0 0 []) (mkS [S0] [] 0 0 []) false; NCh [RB (SWin 1);RB (SWinL 2)]; NDn 3 [S0] [] 0 1 0 (mkS [S1] [] 0 0 []) (mkS [] [] 0 0 []) true]
  | 3, (StD, S1) => [NCh [RB (SWin 1);RB (SFoldL 1)]; NUp 2 [S1] [] 0 1 1 (mkS [] [] 0 0 []) (mkS [S0] [] 0 0 []) false; NCh [RB (SWin 1);RB (SWinL 2)]; NDn 3 [S0] [] 0 1 0 (mkS [S1] [] 0 0 []) (mkS [] [] 0 0 []) true]
