  | 2, (StA, S0) => []
  | 2, (StA, S1) => []
  | 2, (StB, S0) => []
  | 2, (StB, S1) => []
  | 2, (StC, S0) => []
  | 2, (StC, S1) => []
  | 2, (StD, S0) => []
  | 2, (StD, S1) => []
  | 3, (StA, S0) => []
  | 3, (StA, S1) => []
  | 3, (StB, S0) => []
  | 3, (StB, S1) => []
  | 3, (StC, S0) => []
  | 3, (StC, S1) => []
  | 3, (StD, S0) => []
  | 3, (StD, S1) => []
  | 4, (StA, S0) => []
  | 4, (StA, S1) => []
  | 4, (StB, S0) => [NCh [RB (SWin 4);RB (SCycR 1);RB (SWinR 2);RB (SCycL 1 0);RB (SWin 3);RB (SFoldR 1)]; NDn 1 [S1] [] 0 1 0 (mkS [S0] [] 0 0 []) (mkS [] [] 0 0 []) true]
  | 4, (StB, S1) => []
  | 4, (StC, S0) => []
  | 4, (StC, S1) => [NCh [RB (SWin 4);RB (SCycR 1);RB (SWinR 2);RB (SCycL 1 0);RB (SWin 3);RB (SFoldR 1)]; NDn 1 [S1] [] 0 1 0 (mkS [S0] [] 0 0 []) (mkS [] [] 0 0 []) true]
  | 4, (StD, S0) => []
