Lemma bootl_1RB1LA_1LC0RD_0RB0LC_0LA1RD :
  stepn tm 3 InitES = Some (lift (fam_cfg FAM ([0;1], 0, 0))).
Proof.
  assert (H : match csteps tm 3 c0 with
              | Some c => ceqb c (fam_cfg FAM ([0;1], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm 3 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

