  mkLRule (mkC StA (mkS [S0;S1] [] 0 0 []) S1 (mkS [] [] 0 0 []))
          (mkC StA (mkS [S1;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 1.
