Proof. vm_compute. reflexivity. Qed.

Definition farm2_0_1RB1LA_1RC0LD_0LA0RB_1LB1RB : LRule :=
  mkLRule (mkC StC (mkS [S1;S1;S1;S1] [S1;S1] 1 0 []) S0 (mkS [] [] 0 0 []))
          (mkC StC (mkS [S1;S0] [S1;S0] 1 0 [S1;S0;S1;S1]) S0 (mkS [] [] 0 0 [])) 0 1.
