Lemma iarm_reach_1RB1LC_0LA0RB_0RD0LC_1RD1LA : forall d r,
  d < fm_b FAM - 1 -> r < 3 + 1 ->
  ReachL tm (negb (fm_left FAM)) (fm_left FAM)
    (lr_lhs (iarm_1RB1LC_0LA0RB_0RD0LC_1RD1LA d r)) (lr_rhs (iarm_1RB1LC_0LA0RB_0RD0LC_1RD1LA d r)).
Proof.
  intros d r Hd Hr. vm_compute in Hd.
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply narm_reach; [exact nrules_sound_1RB1LC_0LA0RB_0RD0LC_1RD1LA | exact ok_iarm0_0_1RB1LC_0LA0RB_0RD0LC_1RD1LA]. }
    destruct r as [|r].
    { eapply narm_reach; [exact nrules_sound_1RB1LC_0LA0RB_0RD0LC_1RD1LA | exact ok_iarm0_1_1RB1LC_0LA0RB_0RD0LC_1RD1LA]. }
    destruct r as [|r].
    { eapply narm_reach; [exact nrules_sound_1RB1LC_0LA0RB_0RD0LC_1RD1LA | exact ok_iarm0_2_1RB1LC_0LA0RB_0RD0LC_1RD1LA]. }
    destruct r as [|r].
    { eapply narm_reach; [exact nrules_sound_1RB1LC_0LA0RB_0RD0LC_1RD1LA | exact ok_iarm0_3_1RB1LC_0LA0RB_0RD0LC_1RD1LA]. }
    exfalso; lia.
  }
  exfalso; lia.
Qed.

Lemma iarm_lhs_1RB1LC_0LA0RB_0RD0LC_1RD1LA : forall d r,
  d < fm_b FAM - 1 -> r < 3 + 1 ->
  lr_lhs (iarm_1RB1LC_0LA0RB_0RD0LC_1RD1LA d r)
    = cls_conf FAM (cls_side FAM [] (fm_b FAM - 1) r
                      (astride 3 1 r) [d]).
Proof.
  intros d r Hd Hr. vm_compute in Hd.
  destruct d as [|d].
  {
    destruct r as [|r].
