(** ** What this board establishes

    25 of 25 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: from the RULES to [NeverQuasiHaltsSt]

    The arms below are the case split of [LadderCheck.digs_decomp], built
    from the FAMILY rather than mined: interior arms for the digits below the
    top, and fill arms.  Every certificate arm above is one of these with its
    run lengths pinned to their lower bounds, which is why 25 of them
    collapse to 2 here.

    Both classes are indexed by [LadderCheck]'s ONE arm scheme -- flat below
    a threshold, residue-and-stride at or above it.  The interior class runs
    at threshold 0 stride 1, the fill class at threshold 1
    stride 1.

    [board_neverqh] consumes them, the boot, and one chain per state per fill
    arm, and returns the machine-level theorem. *)

(** *** The inner rules: what the nested arms iterate

    2 rule(s), validated like the ladder at both tails opaque. *)
Definition nlad_1RB1LC_0LA1RB_1RD1LA_0LC0RD : list (LRule * list rstep) :=
  [(mkLRule (mkC StB (mkS [] [S1;S1] 1 0 [S1;S1;S0]) S0 (mkS [] [] 0 0 [])) (mkC StB (mkS [] [S1;S1] 1 1 [S1]) S0 (mkS [] [] 0 0 [])) 4 6, [RB (SRotL 1);RB (SWin 1);RB (SCycL 2 0);RB (SWin 4);RB (SCycR 2);RB (SWin 1);RB (SRotL 1);RB (SFoldL 1)]);
   (mkLRule (mkC StB (mkS [S1;S1] [S1;S1] 1 0 [S0;S1]) S0 (mkS [] [] 0 0 [])) (mkC StB (mkS [S1;S1] [S1;S1] 1 1 []) S0 (mkS [] [] 0 0 [])) 4 6, [RB (SWin 2);RB (SCycL 2 0);RB (SWin 2);RB (SCycR 2);RB (SWin 2);RB (SRotL 2);RB (SFoldL 1)])].
Definition nrules_1RB1LC_0LA1RB_1RD1LA_0LC0RD : list LRule := map fst nlad_1RB1LC_0LA1RB_1RD1LA_0LC0RD.
Local Notation nrules := nrules_1RB1LC_0LA1RB_1RD1LA_0LC0RD.

Lemma nladder_ok_1RB1LC_0LA1RB_1RD1LA_0LC0RD : check_ladder tm [] nlad_1RB1LC_0LA1RB_1RD1LA_0LC0RD = true.
Proof. vm_compute. reflexivity. Qed.

Lemma nrules_sound_1RB1LC_0LA1RB_1RD1LA_0LC0RD : Forall (RuleSound tm false false) nrules.
Proof. apply rule_sound_nil. exact nladder_ok_1RB1LC_0LA1RB_1RD1LA_0LC0RD. Qed.

Definition iarm0_0_1RB1LC_0LA1RB_1RD1LA_0LC0RD : LRule :=
  mkLRule (mkC StA (mkS [] [S0;S1] 1 0 [S0;S0]) S0 (mkS [S1] [] 0 0 []))
          (mkC StA (mkS [] [S0;S0] 1 0 [S0;S1]) S0 (mkS [S1] [] 0 0 [])) 0 1.
Definition ch_iarm0_0_1RB1LC_0LA1RB_1RD1LA_0LC0RD : list nseg :=
  [NCh [RB (SWin 1);RB (SWinR 1);RB (SRotL 1)];
   NUp 0 [S1;S0] [] 0 1 0 (mkS [S0] [] 0 0 []) (mkS [] [] 0 0 []) false;
   NCh [RB (SRotL 1);RB (SWin 1);RB (SCycL 2 0);RB (SWin 4);RB (SCycR 2);RB (SWin 2);RB (SCycL 2 0);RB (SWin 6);RB (SCycR 2);RB (SWin 4);RB (SRotL 1);RB (SWin 1)]].
Lemma ok_iarm0_0_1RB1LC_0LA1RB_1RD1LA_0LC0RD :
  check_narm tm false true nrules iarm0_0_1RB1LC_0LA1RB_1RD1LA_0LC0RD ch_iarm0_0_1RB1LC_0LA1RB_1RD1LA_0LC0RD = true.
Proof. vm_compute. reflexivity. Qed.

Definition farm1_0_1RB1LC_0LA1RB_1RD1LA_0LC0RD : LRule :=
  mkLRule (mkC StA (mkS [S0;S1] [S0;S1] 1 0 []) S0 (mkS [S1] [] 0 0 []))
          (mkC StA (mkS [S0;S0] [S0;S0] 1 0 [S0;S1]) S0 (mkS [S1] [] 0 0 [])) 0 1.
Definition ch_farm1_0_1RB1LC_0LA1RB_1RD1LA_0LC0RD : list nseg :=
  [NCh [RB (SWin 1);RB (SWinR 1)];
   NUp 1 [S0;S1] [] 0 1 0 (mkS [] [] 0 0 []) (mkS [] [] 0 0 []) true;
   NCh [RB (SWin 2);RB (SCycL 2 0);RB (SWinL 2);RB (SCycR 2);RB (SWin 4);RB (SCycL 2 0);RB (SWin 1);RB (SWinL 3);RB (SCycR 2);RB (SWin 6)]].
Lemma ok_farm1_0_1RB1LC_0LA1RB_1RD1LA_0LC0RD :
  check_narm tm true true nrules farm1_0_1RB1LC_0LA1RB_1RD1LA_0LC0RD ch_farm1_0_1RB1LC_0LA1RB_1RD1LA_0LC0RD = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB1LC_0LA1RB_1RD1LA_0LC0RD (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1LC_0LA1RB_1RD1LA_0LC0RD
  | _, _ => iarm0_0_1RB1LC_0LA1RB_1RD1LA_0LC0RD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

(** The fill arms, one per arm index and PHASE.  Both tails are known
    empty -- they are the only arms that see the end of the counter -- and
    the arm at index [r] has [r] guaranteed block copies materialised into
    [s_pre], without which it has no chain at all.  [fm1]/[fm2] say how the
    fill target's own guaranteed copies divide about the block.

    The phase is the second index because the fill arm is the ONLY one that
    sees a terminator: it leaves from the terminator of its own phase and
    lands on the terminator of the phase its law names.  The interior arms
    keep the terminator in the opaque tail and are phase-free. *)
Definition farm_1RB1LC_0LA1RB_1RD1LA_0LC0RD (r ph : nat) : LRule :=
  match r, ph with
  | 1, 0 => farm1_0_1RB1LC_0LA1RB_1RD1LA_0LC0RD
  | _, _ => farm1_0_1RB1LC_0LA1RB_1RD1LA_0LC0RD  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_1RB1LC_0LA1RB_1RD1LA_0LC0RD (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | _, _ => 0 end.
Definition fm2_1RB1LC_0LA1RB_1RD1LA_0LC0RD (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 0 | _, _ => 0 end.

(** One chain per UNPINNED INSTRUCTION per fill arm, at the VISIT PHASE
    0.  [fire_of_run_instr] turns each into a fire of that instruction,
    and [tops_cofinal_at] says the tops of that phase keep coming.  The fill
    arm is the counter's overflow, so this is where the rare instruction of
    a sparse row is witnessed. *)
Definition vis_1RB1LC_0LA1RB_1RD1LA_0LC0RD (r : nat) (t : Instr) : list lstep :=
  match r, t with
  | 1, (StA, S0) => [SWin 0]
  | 1, (StA, S1) => [SWinR 3]
  | 1, (StB, S0) => [SWinR 2]
  | 1, (StB, S1) => [SWin 1]
  | 1, (StC, S0) => [SWin 2;SCycL 2 0;SWinL 2;SCycR 2;SWin 4;SCycL 2 0;SWinL 2]
  | 1, (StC, S1) => [SWinR 4]
  | 1, (StD, S0) => [SWin 2;SCycL 2 0;SWinL 2;SCycR 2;SWin 4;SCycL 2 0;SWin 1;SWinL 3;SCycR 2;SWin 2]
  | 1, (StD, S1) => [SWin 2;SCycL 2 0;SWinL 2;SCycR 2;SWin 4;SCycL 2 0;SWinL 3]
  | _, _ => []
  end.

(** ...each after its segment program: a visit that fires past the rounds
    of a nested fill arm first runs that arm's program up to them. *)
Definition vsegs_1RB1LC_0LA1RB_1RD1LA_0LC0RD (r : nat) (t : Instr) : list nseg :=
  match r, t with
  | 1, (StA, S0) => []
  | 1, (StA, S1) => []
  | 1, (StB, S0) => []
  | 1, (StB, S1) => []
  | 1, (StC, S0) => [NCh [RB (SWin 1);RB (SWinR 1)]; NUp 1 [S0;S1] [] 0 1 0 (mkS [] [] 0 0 []) (mkS [] [] 0 0 []) true]
  | 1, (StC, S1) => []
  | 1, (StD, S0) => [NCh [RB (SWin 1);RB (SWinR 1)]; NUp 1 [S0;S1] [] 0 1 0 (mkS [] [] 0 0 []) (mkS [] [] 0 0 []) true]
  | 1, (StD, S1) => [NCh [RB (SWin 1);RB (SWinR 1)]; NUp 1 [S0;S1] [] 0 1 0 (mkS [] [] 0 0 []) (mkS [] [] 0 0 []) true]
  | _, _ => []
  end.

Lemma iarm_reach_1RB1LC_0LA1RB_1RD1LA_0LC0RD : forall d r,
  d < fm_b FAM - 1 -> r < 0 + 1 ->
  ReachL tm (negb (fm_left FAM)) (fm_left FAM)
    (lr_lhs (iarm_1RB1LC_0LA1RB_1RD1LA_0LC0RD d r)) (lr_rhs (iarm_1RB1LC_0LA1RB_1RD1LA_0LC0RD d r)).
Proof.
  intros d r Hd Hr. vm_compute in Hd.
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply narm_reach; [exact nrules_sound_1RB1LC_0LA1RB_1RD1LA_0LC0RD | exact ok_iarm0_0_1RB1LC_0LA1RB_1RD1LA_0LC0RD]. }
    exfalso; lia.
  }
  exfalso; lia.
Qed.

Lemma iarm_lhs_1RB1LC_0LA1RB_1RD1LA_0LC0RD : forall d r,
  d < fm_b FAM - 1 -> r < 0 + 1 ->
  lr_lhs (iarm_1RB1LC_0LA1RB_1RD1LA_0LC0RD d r)
    = cls_conf FAM (cls_side FAM [] (fm_b FAM - 1) r
                      (astride 0 1 r) [d]).
Proof.
  intros d r Hd Hr. vm_compute in Hd.
  destruct d as [|d].
  {
    destruct r as [|r].
    { vm_compute; reflexivity. }
    exfalso; lia.
  }
  exfalso; lia.
Qed.

Lemma iarm_rhs_1RB1LC_0LA1RB_1RD1LA_0LC0RD : forall d r,
  d < fm_b FAM - 1 -> r < 0 + 1 ->
  lr_rhs (iarm_1RB1LC_0LA1RB_1RD1LA_0LC0RD d r)
    = cls_conf FAM (cls_side FAM [] 0 r (astride 0 1 r) [S d]).
Proof.
  intros d r Hd Hr. vm_compute in Hd.
  destruct d as [|d].
  {
    destruct r as [|r].
    { vm_compute; reflexivity. }
    exfalso; lia.
  }
  exfalso; lia.
Qed.

Lemma farm_reach_1RB1LC_0LA1RB_1RD1LA_0LC0RD : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 ->
  ReachL tm true true (lr_lhs (farm_1RB1LC_0LA1RB_1RD1LA_0LC0RD r ph)) (lr_rhs (farm_1RB1LC_0LA1RB_1RD1LA_0LC0RD r ph)).
Proof.
  intros r ph H0 Hr Hph.
  destruct r as [|r].
  { exfalso; lia. }
  destruct r as [|r].
  {
    destruct ph as [|ph].
    { eapply narm_reach; [exact nrules_sound_1RB1LC_0LA1RB_1RD1LA_0LC0RD | exact ok_farm1_0_1RB1LC_0LA1RB_1RD1LA_0LC0RD]. }
    exfalso; lia.
  }
  exfalso; lia.
Qed.

Lemma farm_lhs_1RB1LC_0LA1RB_1RD1LA_0LC0RD : forall r ph, 0 < r -> r < 1 + 1 ->
