  ph < 1 ->
  ReachL tm true true (lr_lhs (farm_1RB1LC_0LC0RB_1RD1LA_0LC1RD r ph)) (lr_rhs (farm_1RB1LC_0LC0RB_1RD1LA_0LC1RD r ph)).
