Lemma farm_lhs_1RB1LC_0LC0RB_1RD1LA_0LC1RD : forall r ph, 0 < r -> r < 2 + 1 ->
  ph < 1 ->
  lr_lhs (farm_1RB1LC_0LC0RB_1RD1LA_0LC1RD r ph)
    = cls_conf FAM (run_side FAM (fm_b FAM - 1) r (astride 2 1 r)
                      0 ph [] []).
Proof.
  intros r ph H0 Hr Hph.
  destruct r as [|r].
  { exfalso; lia. }
  destruct r as [|r].
  {
    destruct ph as [|ph].
    { vm_compute; reflexivity. }
