Lemma farm_rhs_1RB1LC_0LC0RB_1RD1LA_0LC1RD : forall r ph, 0 < r -> r < 2 + 1 ->
  ph < 1 ->
  lr_rhs (farm_1RB1LC_0LC0RB_1RD1LA_0LC1RD r ph)
    = cls_conf FAM (run_side FAM (f_mid (fam_fill FAM ph)) (fm1_1RB1LC_0LC0RB_1RD1LA_0LC1RD r ph)
                      (astride 2 1 r) (fm2_1RB1LC_0LC0RB_1RD1LA_0LC1RD r ph)
                      (f_to (fam_fill FAM ph))
