Lemma fm12_1RB1LC_0LC1RD_1LA0RB_0LC0RB : forall r ph, 0 < r -> r < 2 + 1 ->
  ph < 1 ->
  fm1_1RB1LC_0LC1RD_1LA0RB_0LC0RB r ph + fm2_1RB1LC_0LC1RD_1LA0RB_0LC0RB r ph
  + (length (f_pre (fam_fill FAM ph)) + length (f_suf (fam_fill FAM ph)))
