Lemma bootl_1RB1RA_0LC0RB_1RA0LD_1LA1LD :
  stepn tm 19 InitES = Some (lift (fam_cfg FAM ([0], 0, 0))).
Proof.
  assert (H : match csteps tm 19 c0 with
              | Some c => ceqb c (fam_cfg FAM ([0], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm 19 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** The machine-level theorem, at the INSTRUCTION level, through the nested
    board [LadderCheckNestTr.boardN_neverqhtr]. *)
Theorem nqhtr_1RB1RA_0LC0RB_1RA0LD_1LA1LD : NeverQuasiHaltsTr tm_1RB1RA_0LC0RB_1RA0LD_1LA1LD.
Proof.
  eapply (boardN_neverqhtr tm_1RB1RA_0LC0RB_1RA0LD_1LA1LD pins_1RB1RA_0LC0RB_1RA0LD_1LA1LD FAM 1
                           iarm_1RB1RA_0LC0RB_1RA0LD_1LA1LD 1 1
                           farm_1RB1RA_0LC0RB_1RA0LD_1LA1LD 1 1
                           fm1_1RB1RA_0LC0RB_1RA0LD_1LA1LD fm2_1RB1RA_0LC0RB_1RA0LD_1LA1LD 0
                           nrules vsegs_1RB1RA_0LC0RB_1RA0LD_1LA1LD vis_1RB1RA_0LC0RB_1RA0LD_1LA1LD
                           [0] 0).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_1RB1RA_0LC0RB_1RA0LD_1LA1LD.
  - repeat constructor.
  - vm_compute; lia.
  - lia.
  - lia.
  - exact iarm_reach_1RB1RA_0LC0RB_1RA0LD_1LA1LD.
  - exact iarm_lhs_1RB1RA_0LC0RB_1RA0LD_1LA1LD.
  - exact iarm_rhs_1RB1RA_0LC0RB_1RA0LD_1LA1LD.
  - lia.
  - lia.
  - exact farm_reach_1RB1RA_0LC0RB_1RA0LD_1LA1LD.
  - exact farm_lhs_1RB1RA_0LC0RB_1RA0LD_1LA1LD.
  - exact farm_rhs_1RB1RA_0LC0RB_1RA0LD_1LA1LD.
  - exact nrules_sound_1RB1RA_0LC0RB_1RA0LD_1LA1LD.
  - exact vis_ok_1RB1RA_0LC0RB_1RA0LD_1LA1LD.
  - exact bootl_1RB1RA_0LC0RB_1RA0LD_1LA1LD.
Qed.

